from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, EmailStr, conint
import uuid
app = FastAPI()

class PaymentIn(BaseModel):
    amount: conint(gt=0)
    currency: str
    idempotency_key: str

payments = {}

@app.post("/v1/payments")
def create_payment(p: PaymentIn):
    if p.idempotency_key in payments:
        return payments[p.idempotency_key]
    pid = str(uuid.uuid4())
    record = {"id": pid, "amount": p.amount, "currency": p.currency}
    payments[p.idempotency_key] = record
    return record

def versioned_route(path, version):
    return f"/v{version}{path}"

# Example usage
user_url = versioned_route("/users", 2)
# user_url == "/v2/users"

