from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, EmailStr
app = FastAPI()

class ProfileIn(BaseModel):
    name: str
    email: EmailStr

store = {}

@app.post("/v1/profiles")
def create_profile(profile: ProfileIn, idempotency_key: str = Header(...)):
    if idempotency_key in store:
        return store[idempotency_key]
    pid = len(store) + 1
    record = {"id": pid, "name": profile.name, "email": profile.email}
    store[idempotency_key] = record
    return record

# Explanation: The endpoint extracts the Idempotency-Key header. If the key already exists in the store, the previously created record is returned, preventing duplicate profiles. Otherwise a new profile is created, stored under the key, and returned. This guarantees that retries with the same key are safe.

from pydantic import BaseModel, validator

class StrictList(BaseModel):
    values: list[int]

    @validator('values')
    def check_strict(cls, v):
        if any(v[i] >= v[i+1] for i in range(len(v)-1)):
            raise ValueError('list must be strictly increasing')
        return v

# Test case
try:
    StrictList(values=[1, 3, 5])
    print('valid')
except Exception as e:
    print(e)

try:
    StrictList(values=[1, 2, 2])
except Exception as e:
    print(e)

# Output: valid \n 1 validation error for StrictList \n values \n   list must be strictly increasing (type=value_error)

The client can request /v1/items?type=book. The server parses the optional "type" query parameter and filters the collection before serialization. Implementation example in FastAPI:

@app.get("/v1/items")
def list_items(type: str | None = None):
    all_items = get_all_items()
    if type:
        all_items = [i for i in all_items if i["type"] == type]
    return all_items

This keeps the endpoint generic while allowing clients to retrieve subsets, reducing bandwidth and processing on the client side.
